%[text] ## Feedback Control Experiment
%[text] use PID Controller and compare the performance.
%%
clear; close all;
projectRoot = fileparts(fileparts(mfilename("fullpath")));
run(fullfile(projectRoot, "config", "config.m"));
load(fullfile(projectRoot, "config", "data", "pana_params.mat"));

%%
%[text] ### STEP 1: Design Controller
[plant, plantPath] = load_experiment_plant( ...
    projectRoot, plantDataFile, Ts);
Pd = plant.Pd;
Jn = plant.Jn;
Dn = plant.Dn;
Ndelay = plant.Ndelay;
fprintf("Sample rate: %.0f Hz, plant: %s\n", 1/Ts, plantPath); %[output:2c4d25c6]
s = tf('s');
z = tf('z', Ts);

figure; %[output:2aef6c2f]
bop_ = bop;
bop_.YLim = {[-170, -30];[-180,180]};
bop_.XLim = {[1,1e3]};
Pdn = c2d(1/(Jn*s+Dn)/s,Ts,"tustin")/z^Ndelay;
bode(Pd, Pdn, bop_) %[output:2aef6c2f]
%%
if sampleRateHz == 4e3
    controllerBandwidth = 110;
else
    controllerBandwidth = 80;
end
Kpid = designpid(Dn/Jn, 0, 1/Jn, controllerBandwidth);

Kd = c2d(Kpid, Ts,  "tustin");
figure; %[output:635e2ffe]
margin(Pd*Kd); %[output:635e2ffe]
Smax = 2; % = 6dB

figure; %[output:223b2c92]
nyquist(Pdn*Kd ,Pd*Kd ,nop); hold on; %[output:223b2c92]
theta = 0:0.01:2*pi;
plot(cos(theta)/Smax-1,sin(theta)/Smax,'k--'); hold off; %[output:223b2c92]
% pbaspect([1 1 1]);
legend('nominal','frd'); %[output:223b2c92]
title("Nyquist plot"); %[output:223b2c92]
% Sensitivity plot
figure; %[output:9452a251]
S = feedback(1,Pd*Kd );
Smax_frd = frd(Smax*ones(length(Pd.freq),1),Pd.freq,"FrequencyUnit","Hz");
bop_s = bop;
bop_s.XLim = {[1,1e3]};
bop_s.YLim = {[-60,30]};
bodemag(S,bop_s); hold on; %[output:9452a251]
bodemag(Smax_frd,bop_s,'k--'); %[output:9452a251]
legend('frd'); %[output:9452a251]
title("Sensitivity function"); %[output:9452a251]
%%
%[text] ### STEP 2: FEEDBACK EXPERIMENT
%[text] set reference trajectory
%% パラメータ設定
dist = 0.54;       % Travel distance [m]
v_max = 1.0;      % Maximum velocity [m/s]
a_max = 17.0;      % Maximum acceleration [m/s^2]
t_pause = 1.0;    % Dwell at the turn-around point [s]
t_pre = 1.5;      % Idle time before motion [s]
t_post = 1.5;     % Idle time after motion [s]

traj = generateMyProfile_TrajectTools( ...
    0.0, dist, v_max, a_max/2, Ts, t_pause, t_pre, t_post);
t = traj.time;
r = traj.pos(:);
Tend = t(end);
N = numel(r);
feedbackFlag = 1;

figure %[output:0470815b]
subplot(3,1,1), plot(traj.time, traj.pos),  title('Position'), grid on %[output:0470815b]
subplot(3,1,2), plot(traj.time, traj.vel),  title('Velocity'), grid on %[output:0470815b]
subplot(3,1,3), plot(traj.time, traj.acc),  title('Acceleration'), grid on %[output:0470815b]
%%
%[text] build simulink model "twomass\_exp\_2019a.slx" after executing this section
%[text] Rebuild and redeploy after changing sampleRateHz, the trajectory, or Kd. Set the TwinCAT task to Ts before operating the stage.
set_ff = zeros(N,1);
set_ref = r;
open(fullfile(projectRoot, ModelName))
slbuild(model) %[output:728a5d21] %[output:1f4b209d] %[output:25d51c83]
builtSamplePeriod = Ts;
builtModel = ModelName;
builtAt = datetime("now");
save(fullfile(projectRoot, "config", "data", "feedback_build_info.mat"), ...
    "builtSamplePeriod", "builtModel", "builtAt");
%%
%[text] execute experiment via simulink
%[text] \*make sure to close all simulink files before executing this section
open(fullfile(projectRoot, ModelName))
obtainMeasurement; %[output:1459d898]
t = measurement_time;
y = measurement(5,:); % output position [m]
e = measurement(2,:); % tracking error [m]
r = measurement(3,:);
u = measurement(4,:); % control input [A]
v = measurement(6,:);
torque = measurement(7,:);

figure; plot(diff(y)/Ts) %[output:187f4fb0]
%%
%[text] save experiment data
feedbackResult = struct("t", t, "r", r, "y", y, "e", e, "u", u, ...
    "v", v, "Kd", Kd, "torque", torque, "Ts", Ts, ...
    "plantPath", plantPath, "measurement_metadata", measurement_metadata, ...
    "measurement_source_path", measurement_source_path);
f = save_experiment_result(runDir, "position_feedback_result", feedbackResult); %[output:group:792bc5e0] %[output:2f6a697e]
%%
%[text] ### STEP 3: Analyze the results of the experiment
%[text] download data
load(f);
assert(exist("Ts", "var") == 1, ...
    "The result file must contain Ts for sample-rate-safe analysis.");
load(fullfile(projectRoot, "config", "data", "config.mat"), "bop");
%%
%[text] plot tracking result of feedback control
figure; %[output:341395e5]


ax(1)=subplot(3,1,1); %[output:341395e5]
plot(t,r,t,y); %[output:341395e5]
xlabel("Time [s]"); ylabel("Position [m]"); %[output:341395e5]
xlim([0,max(t)]); %[output:341395e5]
grid on; %[output:341395e5]

ax(2)=subplot(3,1,2); %[output:341395e5]
plot(t,e); %[output:341395e5]
xlabel("Time [s]"); ylabel("Tracking error [m]") %[output:341395e5]
xlim([0,max(t)]); %[output:341395e5]
grid on; %[output:341395e5]

ax(3)=subplot(3,1,3); %[output:341395e5]
plot(t,u); %[output:341395e5]
xlabel("Time [s]"); ylabel("Input [A]"); %[output:341395e5]
xlim([0,max(t)]); %[output:341395e5]
grid on; %[output:341395e5]

linkaxes(ax, 'x'); %[output:341395e5]
save_experiment_figures(runDir, gcf);
%%
%[text] display error norm
norm(e) %[output:9d344e4a]
%%
vr = gradient(r,Ts);
i_fwd = vr > 0.99*max(abs(vr));
i_ret = vr < -0.99*max(abs(vr));

x = r(i_fwd);
u_fwd = u(i_fwd);
u_ret = interp1(flip(r(i_ret)),flip(u(i_ret)),x);

figure; %[output:29e61710]
plot(-x,-(u_fwd+u_ret)/2,-x,(u_fwd-u_ret)/2); %[output:29e61710]
xlabel("Position [m]"); ylabel("Input [A]"); %[output:29e61710]
legend("(forward + return)/2","(forward - return)/2"); %[output:29e61710]
grid on; %[output:29e61710]
save_experiment_figures(runDir, findall(groot, "Type", "figure"));


